import { Table, StringColumn, DateTimeColumn, GuidColumn, ReferenceColumn, IntegerColumn } from '@servicenow/sdk/core'

export const cmn_building = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    label: 'Building',
    name: 'cmn_building',
    schema: {
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        notes: StringColumn({
            label: 'Notes',
            maxLength: 4000,
        }),
        location: ReferenceColumn({
            label: 'Location',
            referenceTable: 'cmn_location',
            referenceFloats: true,
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        floors: IntegerColumn({
            label: [
                {
                    hint: 'Number of floors in building',
                    label: 'Floors',
                    plural: 'Floors',
                    language: 'en',
                },
            ],
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        contact: ReferenceColumn({
            dependent: 'company',
            label: [
                {
                    hint: 'Primary contact for the building',
                    label: 'Contact',
                    plural: 'Contacts',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
    },
})
